// Validate and prepare input data with schema-aligned defaults
const input = $input.first().json;

// Valid ENUM values from schema
const validAgeBands = ['pre_k', 'k_prep', 'grade_1', 'grade_2', 'grade_3', 'grade_4'];
const validCategories = ['bedtime', 'seasonal', 'cultural', 'curriculum', 'emotional_social', 'school', 'family', 'adventure'];
const validIllustrationStyles = ['soft_flat', 'watercolor', 'line_art', 'collage', 'photographic'];
const validReadingModes = ['read_to_me', 'read_with_me', 'read_alone'];

// Age band to age range mapping
const ageRanges = {
  'pre_k': { min: 2, max: 3, level: 'A' },
  'k_prep': { min: 4, max: 5, level: 'A' },
  'grade_1': { min: 6, max: 7, level: 'C' },
  'grade_2': { min: 7, max: 8, level: 'E' },
  'grade_3': { min: 8, max: 9, level: 'G' },
  'grade_4': { min: 9, max: 10, level: 'I' }
};

// Validate and set age_band
const age_band = validAgeBands.includes(input.age_band) ? input.age_band : 'pre_k';
const ageRange = ageRanges[age_band];

// Validate category
const category = validCategories.includes(input.category) ? input.category : 'bedtime';

// Validate illustration style
const illustration_style = validIllustrationStyles.includes(input.illustration_style) 
  ? input.illustration_style : 'soft_flat';

const data = {
  // Core fields
  category: category,
  age_band: age_band,
  theme: input.theme || 'A friendly adventure',
  character_name: input.character_name || 'Sunny',
  page_count: Math.min(Math.max(input.page_count || 4, 2), 12),

  // Age alignment (derived from age_band)
  min_age: ageRange.min,
  max_age: ageRange.max,
  reading_level: input.reading_level || ageRange.level,

  // Arrays
  emotional_focus: Array.isArray(input.emotional_focus) ? input.emotional_focus : ['joy', 'curiosity'],
  sight_words: Array.isArray(input.sight_words) ? input.sight_words : ['the', 'is', 'and', 'a'],

  // Visual
  illustration_style: illustration_style,

  // Generate unique story code
  story_code: 'SS-' + age_band.toUpperCase().replace('_', '') + '-' + Date.now().toString().slice(-6),

  // Optional fields
  author: input.author || 'StorySprout AI',
  story_path_id: input.story_path_id || null
};

return { json: data };

