// Parse Claude response and merge with input data
const response = $input.first().json;
const inputData = $('Validate Input').first().json;

let storyData;

try {
  const content = response.content[0].text;

  // Clean up response - remove markdown if present
  let jsonString = content;
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonString = jsonMatch[1].trim();
  } else {
    const rawJsonMatch = content.match(/\{[\s\S]*\}/);
    if (rawJsonMatch) {
      jsonString = rawJsonMatch[0];
    }
  }

  storyData = JSON.parse(jsonString);

} catch (e) {
  throw new Error('Failed to parse story JSON: ' + e.message);
}

// Calculate estimated read time (roughly 0.5 min per page for young readers)
const estimatedReadTime = Math.ceil(storyData.pages.length * 0.5);

// Build sight_word_positions for each page
const pagesWithPositions = storyData.pages.map(page => {
  const positions = [];
  const words = page.text_content.toLowerCase().split(/\s+/);

  inputData.sight_words.forEach(sightWord => {
    words.forEach((word, index) => {
      // Clean punctuation for comparison
      const cleanWord = word.replace(/[^a-z]/g, '');
      if (cleanWord === sightWord.toLowerCase()) {
        positions.push({ word: sightWord, index: index });
      }
    });
  });

  return {
    ...page,
    sight_word_positions: positions
  };
});

// Return merged data matching schema structure
return {
  json: {
    // From input validation
    story_code: inputData.story_code,
    age_band: inputData.age_band,
    min_age: inputData.min_age,
    max_age: inputData.max_age,
    reading_level_system: 'guided',
    reading_level: inputData.reading_level,
    category: inputData.category,
    illustration_style: inputData.illustration_style,
    author: inputData.author,
    story_path_id: inputData.story_path_id,
    character_name: inputData.character_name,

    // From Claude generation
    title: storyData.title,
    subtitle: storyData.subtitle || '',
    themes: storyData.themes || [],
    curriculum_alignment: storyData.curriculum_alignment || [],
    learning_objectives: storyData.learning_objectives || [],

    // Combined/computed
    emotional_focus: inputData.emotional_focus,
    sight_words: inputData.sight_words,
    vocabulary_tier: inputData.age_band === 'pre_k' || inputData.age_band === 'k_prep' ? 1 : 2,
    estimated_read_time_minutes: estimatedReadTime,
    page_count: storyData.pages.length,
    modes_supported: ['read_to_me', 'read_with_me', 'read_alone'],

    // Pages with computed sight word positions
    pages: pagesWithPositions
  }
};

// Prepare pages for batch processing
const storyResponse = $('Supabase - Create Story').first().json;
const storyData = $('Parse Story Response').first().json;

// Supabase returns array with Prefer: return=representation
const story = Array.isArray(storyResponse) ? storyResponse[0] : storyResponse;

if (!story || !story.id) {
  throw new Error('Story creation failed - no ID returned. Response: ' + JSON.stringify(storyResponse));
}

return storyData.pages.map(page => ({
  json: {
    story_id: story.id,
    story_code: story.story_code,
    page_number: page.page_number,
    text_content: page.text_content,
    illustration_description: page.illustration_description,
    illustration_alt_text: page.illustration_description.substring(0, 200),
    sight_word_positions: page.sight_word_positions,
    age_band: storyData.age_band,
    illustration_style: storyData.illustration_style,
    character_name: storyData.character_name
  }
}));

