// Prepare data for upload
const loopData = $('Loop Over Pages').first().json;
const imageData = $input.first();

const binaryData = imageData.binary?.data;
if (!binaryData) {
  throw new Error('No image binary data received');
}

return {
  json: {
    story_id: loopData.story_id,
    story_code: loopData.story_code,
    page_number: loopData.page_number,
    text_content: loopData.text_content,
    illustration_alt_text: loopData.illustration_alt_text,
    sight_word_positions: loopData.sight_word_positions,
    filename: `page-${loopData.page_number}.png`
  },
  binary: {
    data: binaryData
  }
};

// Build public URL and prepare page record
const pageData = $('Prepare Upload').first().json;
const supabaseUrl = 'YOUR_SUPABASE_URL';

const publicUrl = `${supabaseUrl}/storage/v1/object/public/story-images/${pageData.story_id}/${pageData.filename}`;

return {
  json: {
    story_id: pageData.story_id,
    page_number: pageData.page_number,
    text_content: pageData.text_content,
    illustration_url: publicUrl,
    illustration_alt_text: pageData.illustration_alt_text,
    sight_word_positions: pageData.sight_word_positions
  }
};

